{"path":"/testbed/config_loader.py","content":""""Profile loading for acme-configkit.

See ``README.md`` and ``docs/coding-standard.md`` for the loading contract. ``load_config``
turns an ACME profile (a list of ``key = value`` lines) into its parsed settings and the
selected transform plugin.
"""

from __future__ import annotations

import ast

from plugins import BUILTIN_PLUGINS


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    Returns ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``:
    every non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a built-in transform plugin by name (an
    instance, or ``None`` when the profile sets no plugin).
    """
    settings: dict = {}
    plugin = None
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, raw = line.partition("=")
        if not sep:
            raise ValueError(f"invalid profile line (expected 'key = value'): {line!r}")
        key, raw = key.strip(), raw.strip()
        value = _parse_value(raw, key)
        if key == "plugin":
            plugin = _load_plugin(value)
        else:
            settings[key] = value
    return {"settings": settings, "plugin": plugin}


def _parse_value(raw: str, key: str):
    """Parse a profile value to a Python object.

    Uses ``ast.literal_eval`` rather than ``eval``: it covers every value form the contract
    requires (scalars, strings, lists, dicts, tuples, booleans, ``None``) without executing
    arbitrary code from a profile file.
    """
    try:
        return ast.literal_eval(raw)
    except (ValueError, SyntaxError) as exc:
        raise ValueError(f"invalid value for {key!r}: {raw!r}") from exc


def _load_plugin(name):
    """Instantiate the built-in transform plugin selected by a profile's ``plugin`` key."""
    try:
        transform_cls = BUILTIN_PLUGINS[name]
    except (KeyError, TypeError):
        raise ValueError(
            f"unknown plugin {name!r}; expected one of {sorted(BUILTIN_PLUGINS)}"
        ) from None
    return transform_cls()
